import{_ as o,o as n,c,a0 as i}from"./chunks/framework.DhQjJcnt.js";const g=JSON.parse('{"title":"Skill: /grill-dev","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/grill-dev.md","filePath":"references/skills/grill-dev.md"}'),t={name:"references/skills/grill-dev.md"};function a(d,e,l,r,s,h){return n(),c("div",null,[...e[0]||(e[0]=[i('<h1 id="skill-grill-dev" tabindex="-1">Skill: <code>/grill-dev</code> <a class="header-anchor" href="#skill-grill-dev" aria-label="Permalink to &quot;Skill: `/grill-dev`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>grill-dev</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/grill-dev &lt;page-id/slug&gt;</code></li><li>Thường được gọi sau khi <code>grill-bqa</code> (hoặc <code>spec</code>) đã hoàn tất việc chốt nghiệp vụ (<code>grillStatus.bqaOpen: done</code>).</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>File <code>*.bundle.yaml</code> chứa thiết kế UI và logic.</li><li>File trung gian <code>ir/design.yaml</code>.</li><li>File contract backend <code>api/&lt;seq&gt;/01-backend-spec.yaml</code> (nếu có).</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Cập nhật nhánh <code>gen:</code> trong <code>*.bundle.yaml</code> (<code>codegen.profile</code>, <code>entity</code>, <code>module</code>, <code>tags</code>, <code>ui.*</code>).</li><li>Bổ sung các Endpoint actions (<code>/create</code>, <code>/{id}/update</code>...) vào file <code>01-backend-spec.yaml</code>.</li><li>Sinh các mã lỗi <code>#err:*</code> và cấu trúc Hashtag phục vụ Gen Code (<code>#needs-component</code>, <code>#use-store</code>, <code>#reuse-api</code>).</li><li>Trạng thái <code>grillStatus.dev: done</code>.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Kỹ năng <strong>độc quyền</strong> dành riêng cho việc rà soát kỹ thuật (Technical Review &amp; Engineering). <strong>Không</strong> dùng để tranh luận lại logic Business hay UX copy.</li><li>Kiểm tra tính sẵn sàng của Codegen: Bắt buộc cấu hình chính xác <code>codegen.profile</code> (vd: <code>auth</code>, <code>admin-crud</code>, <code>list</code>, <code>not-found</code>, <code>error</code>) để hệ thống biết rẽ nhánh sinh code vào thư mục Frontend phù hợp (vd: <code>src/app/(auth)/</code> hay <code>src/app/(dashboard)/</code>).</li><li>Quản lý Component: Rà soát nếu màn hình quá phức tạp ($\\ge 3$ cấp) phải gắn <code>#use-store</code> để dùng Pinia/Zustand. Bắt buộc tách form ra component riêng. Phân tích các khối UI phức tạp để đề xuất <code>#needs-component: MoBlockName</code>.</li><li>Kiểm tra API Contract: Bắt buộc tuân thủ suffix chuẩn (vd: <code>/create</code>, <code>/{id}/delete</code>), không dùng RESTful mù mờ. Nếu gọi lại API có sẵn thì phải dùng <code>#reuse-api</code>.</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li><strong>Trước đó:</strong> Nhận đầu vào từ <code>/grill-bqa</code> (hoặc <code>/spec</code>).</li><li><strong>Sau đó:</strong><ul><li>Chuyển giao sang <code>bộ code FE</code> để sinh code prototype (<code>/prototype</code>).</li><li>Nếu xung đột giữa Code và Business -&gt; Gọi <code>/grill-docs</code>.</li><li>Nếu thông tin Legacy bị thiếu -&gt; Gọi <code>/update-spec-legacy</code>.</li></ul></li></ul><h2 id="chu-y-quan-trong" tabindex="-1">Chú ý quan trọng <a class="header-anchor" href="#chu-y-quan-trong" aria-label="Permalink to &quot;Chú ý quan trọng&quot;">​</a></h2><ul><li><strong>Cấm đoán (Out of scope):</strong> Tuyệt đối không sinh Markdown reports, không xuất code mẫu (FastAPI, Axios...). Nhiệm vụ duy nhất là cập nhật metadata cấu hình YAML cho Codegen engine.</li><li><strong>Hard gate (Chốt chặn):</strong> Không bao giờ được đánh dấu <code>grillStatus.dev: done</code> nếu <code>bundle.gen</code> vẫn thiếu <code>codegen.profile</code> hoặc các profile CRUD mà lại thiếu <code>entity</code>/<code>module</code>.</li><li><strong>Luật AskQuestion Tech Debt:</strong> Khi thiếu các thông tin kỹ thuật cốt lõi để gen code (như cấu hình profile, tham số entity, hoặc endpoint action), Agent phải gọi Form AskQuestion đưa ra lựa chọn dự đoán (Recommended). Form <strong>BẮT BUỘC</strong> phải có tuỳ chọn <code>&quot;Log as Tech Debt (Pending)&quot;</code>.</li><li>Nếu người dùng chọn <code>&quot;Log as Tech Debt&quot;</code>, phải ghi vào <code>qa/open/QA-&lt;bundle.id&gt;-NNNN.yaml</code> và giữ nguyên trạng thái <code>grillStatus.dev: pending</code>. Không được tự ý cho pass.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/grill-dev</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',20)])])}const p=o(t,[["render",a]]);export{g as __pageData,p as default};
